<div class="page-title">Review Goals</div><p class="page-subtitle">Reusable goals for Day, Week, Month and Year Pre/Post Reviews.</p>
<div class="card"><h2>Add Goal</h2><form method="post" class="grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><p><label>Goal</label><input name="name" list="goal-library" maxlength="160" placeholder="e.g. Trade only A+ setups" required><datalist id="goal-library"><?php foreach($goals as $g):?><option value="<?=e($g['name'])?>"><?php endforeach;?></datalist></p><p><label>Type</label><select name="goal_type"><option value="process">Process</option><option value="risk">Risk</option><option value="psychology">Psychology</option><option value="performance">Performance</option><option value="custom">Custom</option></select></p><p class="filter-actions"><button>Add Goal</button></p></form></div>
<div class="card table-wrap"><table><thead><tr><th>Goal</th><th>Type</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($goals as $g):?><tr><td><?=e($g['name'])?></td><td><span class="badge"><?=e(ucfirst($g['goal_type']))?></span></td><td><?=e($g['created_at'])?></td><td><form method="post" onsubmit="return confirm('Remove this goal from future reviews?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="goal_id" value="<?=e($g['id'])?>"><button class="secondary">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div>
